<?php
namespace Tests\Feature;
use App\Actions\Event\IssueEventTicket;use App\Actions\Event\ValidateEventTicket;use App\Models\CatalogEntity;use App\Models\CatalogOffer;use App\Models\EventTicketType;use App\Models\Mitra;use App\Models\ServiceType;use App\Models\User;use Database\Seeders\FoundationReferenceSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use Spatie\Permission\PermissionRegistrar;use Tests\TestCase;
class EventModuleTest extends TestCase
{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(FoundationReferenceSeeder::class);setPermissionsTeamId(null);}public function test_event_deadline_and_public_lifecycle():void{[$owner,$mitra,$entity]=$this->event();$this->get(route('event.show',$entity->slug))->assertNotFound();$entity->update(['status'=>'published','published_at'=>now()]);$this->get(route('event.show',$entity->slug))->assertOk()->assertSee($entity->name);$this->assertTrue($entity->event->registration_deadline->lessThan($entity->event->ends_at));}
public function test_ticket_quota_and_qr_are_single_use():void{[$owner,$mitra,$entity]=$this->event();$offer=CatalogOffer::create(['mitra_id'=>$mitra->id,'catalog_entity_id'=>$entity->id,'offer_type'=>'event_ticket','sku'=>'EV-TEST','name'=>'Reguler','price'=>50000,'status'=>'active']);$type=EventTicketType::create(['event_id'=>$entity->event->id,'catalog_offer_id'=>$offer->id,'name'=>'Reguler','quota'=>1]);$consumer=User::factory()->create();[$ticket,$token]=app(IssueEventTicket::class)->execute($type,$consumer,$owner);$gatekeeper=User::factory()->create();$validated=app(ValidateEventTicket::class)->execute($token,$gatekeeper,$mitra->id);$this->assertSame('used',$validated->status->value);$this->assertDatabaseHas('event_ticket_validation_logs',['event_ticket_id'=>$ticket->id,'result'=>'accepted']);$this->expectException(ValidationException::class);app(ValidateEventTicket::class)->execute($token,$gatekeeper,$mitra->id);}
public function test_ticket_cannot_validate_across_tenant_and_issue_over_quota():void{[$owner,$mitra,$entity]=$this->event();$offer=CatalogOffer::create(['mitra_id'=>$mitra->id,'catalog_entity_id'=>$entity->id,'offer_type'=>'event_ticket','sku'=>'EV-LIMIT','name'=>'VIP','price'=>100000,'status'=>'active']);$type=EventTicketType::create(['event_id'=>$entity->event->id,'catalog_offer_id'=>$offer->id,'name'=>'VIP','quota'=>1]);[$ticket,$token]=app(IssueEventTicket::class)->execute($type,User::factory()->create(),$owner);$other=Mitra::factory()->for(User::factory(),'owner')->create();try{app(ValidateEventTicket::class)->execute($token,User::factory()->create(),$other->id);$this->fail('Cross tenant validation harus ditolak.');}catch(ValidationException){$this->assertSame('issued',$ticket->fresh()->status->value);}$this->expectException(ValidationException::class);app(IssueEventTicket::class)->execute($type,User::factory()->create(),$owner);}
private function event():array{$owner=User::factory()->create();$mitra=Mitra::factory()->for($owner,'owner')->create(['status'=>'active','approved_at'=>now()]);$service=ServiceType::where('code','event')->firstOrFail();$mitra->features()->create(['service_type_id'=>$service->id,'status'=>'enabled']);$entity=CatalogEntity::create(['mitra_id'=>$mitra->id,'service_type_id'=>$service->id,'name'=>'Festival Tegal','slug'=>'festival-'.str()->lower(str()->random(5)),'description'=>'Festival budaya lokal untuk seluruh keluarga.','address'=>'Tegal','status'=>'draft']);$entity->event()->create(['event_type'=>'festival','starts_at'=>now()->addWeek(),'ends_at'=>now()->addWeek()->addHours(5),'registration_deadline'=>now()->addDays(5)]);return[$owner,$mitra,$entity->fresh('event')];}}
